<script setup lang="ts">
import { computed, ref } from 'vue'
import { filterTools, toolCategories, type ToolCategory } from '../toolRegistry'
import AppIcon from './AppIcon.vue'
import ToolSurface from './shell/ToolSurface.vue'

const search = ref('')
const visibleTools = computed(() => filterTools(search.value))
const toolsInCategory = (category: ToolCategory) => visibleTools.value.filter((tool) => tool.category === category)
</script>

<template>
  <ToolSurface>
    <template #tabs><div class="all-tools-tab">All tools</div></template>
    <section class="dashboard" aria-labelledby="dashboard-title">
      <header><p>MYDEVTOOLS / WORKSPACE</p><h1 id="dashboard-title" data-test-id="dashboard-title" tabindex="-1">Developer tools, ready when you are.</h1><span>Fast, focused utilities for the small jobs that keep your work moving.</span><label class="dashboard-search" for="tool-search"><AppIcon name="search" /><span class="sr-only">Search developer tools</span><input id="tool-search" v-model="search" data-test-id="tool-search" type="search" placeholder="Search tools, formats, or tasks" autocomplete="off" /><kbd>/</kbd></label></header>
      <div v-if="visibleTools.length" class="tool-sections"><section v-for="category in toolCategories" v-show="toolsInCategory(category).length" :key="category"><div class="category-heading"><h2>{{ category }}</h2><span>{{ toolsInCategory(category).length }} tools</span></div><div class="tool-grid"><router-link v-for="tool in toolsInCategory(category)" :key="tool.id" :to="tool.path" class="tool-card" :data-test-id="`tool-card-${tool.id}`" @pointerenter="tool.loader()"><AppIcon :name="tool.icon" /><span><strong>{{ tool.name }}</strong><small>{{ tool.description }}</small></span><AppIcon name="chevron" /></router-link></div></section></div>
      <div v-else class="no-results" data-test-id="no-search-results" role="status"><AppIcon name="search" /><h2>No tools found</h2><p>Try another name, category, or keyword.</p><button class="btn" type="button" @click="search = ''">Clear search</button></div>
    </section>
  </ToolSurface>
</template>

